SELECT c.id, c.course_no AS courseNo, c.name, c.credit, c.hours, c.teacher_id AS teacherId, t.teacher_name AS teacherName, c.semester, c.year, c.max_students AS maxStudents, c.day_of_week AS dayOfWeek, c.start_time AS startTime, c.end_time AS endTime, c.classroom, c.max_credits AS maxCredits, c.status, c.description, c.study_nature AS studyNature, c.textbook, c.external_selection AS externalSelection, c.remark, DATE_FORMAT(c.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, DATE_FORMAT(c.update_time, '%Y-%m-%d %H:%i:%s') AS updateTime FROM course c LEFT JOIN teacher t ON c.teacher_id = t.id
AND c.name LIKE CONCAT('%', #{name}, '%')
AND c.course_no LIKE CONCAT('%', #{courseNo}, '%')
AND c.status = #{status}
AND c.semester = #{semester}
ORDER BY c.create_time DESC

SELECT c.id, c.course_no AS courseNo, c.name, c.credit, c.hours, c.teacher_id AS teacherId, t.teacher_name AS teacherName, c.semester, c.year, c.max_students AS maxStudents, c.day_of_week AS dayOfWeek, c.start_time AS startTime, c.end_time AS endTime, c.classroom, c.max_credits AS maxCredits, c.status, c.description, c.study_nature AS studyNature, c.textbook, c.external_selection AS externalSelection, c.remark, DATE_FORMAT(c.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, DATE_FORMAT(c.update_time, '%Y-%m-%d %H:%i:%s') AS updateTime FROM course c LEFT JOIN teacher t ON c.teacher_id = t.id
AND c.name LIKE CONCAT('%', #{name}, '%')
AND c.course_no LIKE CONCAT('%', #{courseNo}, '%')
AND c.status = #{status}
AND c.semester = #{semester}
ORDER BY c.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM course c


        AND c.name LIKE CONCAT('%', #{name}, '%')


        AND c.course_no LIKE CONCAT('%', #{courseNo}, '%')


        AND c.status = #{status}


        AND c.semester = #{semester}
